<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ArrowLeft, Delete, Document, Edit, Link, Plus, Remove, Select, ShoppingCart } from '@element-plus/icons-vue'
import ImageUpload from './ImageUpload.vue'
import DocumentAssets from './DocumentAssets.vue'

const props = withDefaults(defineProps<{
  record: Record<string, any>
  categories: Array<{ id: number; name: string }>
  canManage?: boolean
  showPrice?: boolean
  startEditing?: boolean
  canDownload?: boolean
}>(), { canManage: false, showPrice: false, startEditing: false, canDownload:false })

const emit = defineEmits<{ back: []; save: [value: Record<string, any>]; savePrice: [value: Record<string, any>]; delete: []; relate: [kind: string]; openRelation: [relation: any] }>()
const editing = ref(false)
const activeTab = ref('overview')
const activeImage = ref('')
const draft = reactive<Record<string, any>>({})
const dynamicFields = ref<Array<{ key:string; value:string; unit:string; group:string; highlight:boolean; dataType:string }>>([])
const tenderFields = ref<Array<{ name:string; value:string; unit:string; group:string; highlight:boolean; dataType:string }>>([])
const galleryText = ref(''), tagsText = ref(''), featuresText = ref(''), boundariesText = ref('')
const galleryUpload = ref('')
const priceEditing = ref(false)
const priceDraft = reactive({ reference_price:0, currency:'CNY', tax_included:true, tax_rate:13, valid_until:'', notes:'' })
const productTypes = [{label:'硬件产品',value:'HARDWARE'},{label:'软件产品',value:'SOFTWARE_PRODUCT'},{label:'系统产品',value:'SYSTEM_PRODUCT'},{label:'配套设备',value:'ACCESSORY'}]
const typeName = computed(() => productTypes.find((item) => item.value === props.record.productType)?.label || '硬件产品')
const recommendations: Record<string, string[]> = {HARDWARE:['探测距离','工作频段','更新率','最大目标数','防护等级','工作温度'],SOFTWARE_PRODUCT:['部署方式','操作系统','数据库','功能模块数','支持设备数'],SYSTEM_PRODUCT:['部署架构','适用规模','交付周期','能力覆盖'],ACCESSORY:['接口类型','供电方式','安装方式','防护等级']}
const gallery = computed(() => props.record.gallery?.length ? props.record.gallery : [{ image:props.record.mainImage || '/assets/product-radar.png', title:props.record.name }])
const quickMetrics = computed(() => (props.record.parameters || []).filter((item:any) => item.highlight).sort((a:any,b:any) => (a.sortOrder || 0) - (b.sortOrder || 0)).slice(0,6))
const allRelations = computed(() => {
  const legacy = (props.record.capabilities || []).map((item:any) => ({ ...item, type:'model-capabilities' }))
  const modern = props.record.relations || []
  const seen = new Set(modern.map((item:any) => item.type + ':' + item.id))
  return [...modern, ...legacy.filter((item:any) => !seen.has(item.type + ':' + item.id))]
})
const relationGroups = computed(() => Object.fromEntries(['model-capabilities','software','algorithms','scenes','solutions','products'].map((type) => [type, allRelations.value.filter((item:any) => item.type === type)])))
const groupedParameters = computed(() => {
  const groups: Record<string, any[]> = {}
  for (const item of props.record.parameters || []) (groups[item.group || '基础参数'] ||= []).push(item)
  return groups
})
const tabs = computed(() => [
  ['overview','产品概览'],['parameters','技术参数'],['models','模型能力'],['software','软件/算法'],['boundaries','能力边界'],['scenes','推荐场景'],
  ...(props.showPrice ? [['price','价格信息']] : []), ['tender','招投标参数'],['documents','资料附件'],['training','相关培训'],
] as string[][])

function resetDraft() {
  Object.assign(draft, { name:props.record.name,product_type:props.record.productType,model_code:props.record.primaryModel||props.record.modelCode,product_code:props.record.productCode||'',product_series:props.record.productSeries||'',current_version:props.record.currentVersion||'',category_id:props.record.categoryId,summary:props.record.summary,description:props.record.description||'',status:props.record.status,data_status:props.record.dataStatus||'CONFIRMED',main_image:props.record.mainImage||'' })
  dynamicFields.value = (props.record.parameters || []).map((item:any) => ({ key:item.name,value:String(item.value ?? ''),unit:item.unit||'',group:item.group||'基础参数',highlight:!!item.highlight,dataType:item.dataType||'TEXT' }))
  tenderFields.value = (props.record.tenderParameters || props.record.parameters || []).map((item:any) => ({ name:item.name,value:String(item.value ?? ''),unit:item.unit||'',group:item.group||'基础参数',highlight:!!item.highlight,dataType:item.dataType||'TEXT' }))
  galleryText.value = (props.record.gallery || []).map((item:any) => [item.image,item.title||''].join('|')).join('\n')
  tagsText.value = (props.record.tags || []).join('\n')
  featuresText.value = (props.record.features || []).map((item:any) => [item.title,item.description||'',item.icon||''].join('|')).join('\n')
  boundariesText.value = (props.record.boundaries || []).join('\n')
}
function beginEdit(){ resetDraft(); editing.value = true }
function addField(key=''){ dynamicFields.value.push({key,value:'',unit:'',group:'基础参数',highlight:false,dataType:'TEXT'}) }
const textLines = (value:string) => value.split('\n').map((item) => item.trim()).filter(Boolean)
function save(){
  const parameters = dynamicFields.value.filter((item) => item.key.trim()).map((item,index) => ({name:item.key.trim(),value:item.value,unit:item.unit,group:item.group,highlight:item.highlight,dataType:item.dataType,sortOrder:index}))
  const galleryPayload = textLines(galleryText.value).map((line,index) => { const [image,title=''] = line.split('|'); return {image,title,sortOrder:index} })
  const features = textLines(featuresText.value).map((line,index) => { const [title,description='',icon=''] = line.split('|'); return {title,description,icon,sortOrder:index} })
  const tenderParameters=tenderFields.value.filter(item=>item.name.trim()).map((item,index)=>({...item,name:item.name.trim(),sortOrder:index}))
  emit('save',{...draft,parameters,tenderParameters,gallery:galleryPayload,tags:textLines(tagsText.value),features,boundaries:textLines(boundariesText.value)})
  editing.value = false
}
function beginPriceEdit(){ Object.assign(priceDraft,{reference_price:props.record.price?.referencePrice||0,currency:props.record.price?.currency||'CNY',tax_included:props.record.price?.taxIncluded??true,tax_rate:props.record.price?.taxRate??13,valid_until:props.record.price?.validUntil?.slice(0,10)||'',notes:props.record.price?.notes||''}); priceEditing.value=true }
function savePrice(){ emit('savePrice',{...priceDraft,valid_until:priceDraft.valid_until||null}); priceEditing.value=false }
function relationLabel(type:string){ return ({'model-capabilities':'模型能力',software:'软件',algorithms:'算法',scenes:'场景',solutions:'方案',products:'产品'} as Record<string,string>)[type] || type }
function money(){ return `${props.record.price?.currency === 'CNY' ? '¥' : props.record.price?.currency || ''} ${Number(props.record.price?.referencePrice || 0).toLocaleString()}` }
function addGalleryUpload(asset:any){galleryText.value += (galleryText.value?'\n':'')+[asset.url,asset.name||'产品图片'].join('|');galleryUpload.value=''}
watch(() => props.record.id, () => { resetDraft(); editing.value = props.startEditing; activeImage.value = gallery.value[0]?.image || ''; activeTab.value='overview' }, { immediate:true })
watch(() => props.startEditing, (value) => { if(value) beginEdit() })
</script>

<template>
  <section class="product-detail-page">
    <div class="detail-nav"><el-button link :icon="ArrowLeft" @click="emit('back')">产品中心 / {{ record.name }}</el-button></div>
    <header class="product-hero">
      <div class="product-gallery"><div class="product-image"><img :src="activeImage || gallery[0]?.image" :alt="record.name"></div><div class="gallery-thumbs"><button v-for="item in gallery.slice(0,4)" :key="item.image" :class="{active:(activeImage||gallery[0]?.image)===item.image}" @click="activeImage=item.image"><img :src="item.image" :alt="item.title||record.name"></button></div></div>
      <div class="hero-copy"><div class="eyebrow">{{ typeName }} / {{ record.category }}</div><h1>{{ record.name }}</h1><div class="hero-identity"><strong>{{ record.modelCode }}</strong><span>{{ record.currentVersion || '版本待维护' }}</span><el-tag :type="record.status==='ON_SALE'?'success':'info'" effect="plain">{{ record.status==='ON_SALE'?'在售':'停售' }}</el-tag></div><p>{{ record.summary || '暂无一句话简介' }}</p><div v-if="quickMetrics.length" class="quick-metrics"><div v-for="item in quickMetrics" :key="item.id||item.name"><strong>{{ item.value }}{{ item.unit }}</strong><span>{{ item.name }}</span></div></div><div v-else class="quick-metrics empty"><span>核心指标待产品经理维护</span></div></div>
      <aside class="hero-business"><el-button type="primary" :icon="ShoppingCart">加入配单</el-button><el-button :icon="Document" @click="activeTab='documents'">查看资料</el-button><el-button v-if="canManage" :icon="Edit" @click="beginEdit">编辑产品</el-button><div v-if="showPrice" class="price-card"><span>参考报价{{ record.price?.taxIncluded?'（含税）':'' }}</span><strong v-if="record.price">{{ money() }}</strong><b v-else>价格待维护</b><small>仅 PRICE_VIEW 可见</small></div><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除产品</el-button></aside>
    </header>
    <div v-if="editing" class="edit-banner"><span>正在同页编辑产品知识</span><div><el-button @click="editing=false">取消</el-button><el-button type="primary" :icon="Select" @click="save">保存修改</el-button></div></div>
    <nav class="detail-tabs" aria-label="产品详情导航"><button v-for="tab in tabs" :key="tab[0]" :class="{active:activeTab===tab[0]}" @click="activeTab=tab[0]">{{ tab[1] }}</button></nav>

    <div v-if="editing&&['overview','parameters','boundaries','tender'].includes(activeTab)" class="product-section edit-surface">
      <div class="section-head"><div><h2>产品身份与内容</h2><p>保存后仍回到同一套产品化详情页。</p></div></div>
      <el-form label-position="top" class="edit-grid"><el-form-item label="产品名称"><el-input v-model="draft.name"/></el-form-item><el-form-item label="产品类型"><el-select v-model="draft.product_type"><el-option v-for="item in productTypes" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="产品编码"><el-input v-model="draft.product_code"/></el-form-item><el-form-item label="产品系列"><el-input v-model="draft.product_series"/></el-form-item><el-form-item label="主型号"><el-input v-model="draft.model_code"/></el-form-item><el-form-item label="当前版本"><el-input v-model="draft.current_version"/></el-form-item><el-form-item label="分类"><el-select v-model="draft.category_id"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="销售状态"><el-select v-model="draft.status"><el-option label="在售" value="ON_SALE"/><el-option label="停售" value="OFF_SALE"/></el-select></el-form-item><el-form-item label="主图地址"><el-input v-model="draft.main_image"/></el-form-item><el-form-item label="数据状态"><el-select v-model="draft.data_status"><el-option label="已确认" value="CONFIRMED"/><el-option label="待确认" value="PENDING"/></el-select></el-form-item><el-form-item label="一句话简介" class="span-2"><el-input v-model="draft.summary" type="textarea" :rows="2"/></el-form-item><el-form-item label="详细介绍" class="span-2"><el-input v-model="draft.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="图片图库" class="span-2"><el-input v-model="galleryText" type="textarea" placeholder="每行：图片地址|图片标题"/></el-form-item><el-form-item label="产品标签" class="span-2"><el-input v-model="tagsText" type="textarea" placeholder="每行一个标签"/></el-form-item><el-form-item label="主要特性" class="span-2"><el-input v-model="featuresText" type="textarea" placeholder="每行：特性名称|说明|图标名"/></el-form-item><el-form-item label="能力边界" class="span-2"><el-input v-model="boundariesText" type="textarea" placeholder="每行一项"/></el-form-item></el-form>
      <div class="section-head parameter-edit-head"><div><h2>动态技术参数</h2><p>按分组、排序和重点标记驱动卡片与 Hero 指标。</p></div><el-dropdown trigger="click" @command="addField"><el-button :icon="Plus">添加参数</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="field in recommendations[draft.product_type]||[]" :key="field" :command="field">{{ field }}</el-dropdown-item><el-dropdown-item divided command="">自定义字段</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
      <div class="dynamic-editor"><div v-for="(field,index) in dynamicFields" :key="index"><el-input v-model="field.key" placeholder="字段名称"/><el-input v-model="field.value" placeholder="字段内容"/><el-input v-model="field.unit" placeholder="单位"/><el-input v-model="field.group" placeholder="参数分组"/><el-select v-model="field.dataType"><el-option label="文本" value="TEXT"/><el-option label="数值" value="NUMBER"/><el-option label="布尔" value="BOOLEAN"/></el-select><el-checkbox v-model="field.highlight" label="重点"/><el-button :icon="Remove" circle aria-label="删除参数" @click="dynamicFields.splice(index,1)"/></div></div>
      <div v-if="activeTab==='overview'" class="asset-editors"><ImageUpload v-model="draft.main_image" label="产品主图"/><ImageUpload v-model="galleryUpload" label="新增图库图片" @uploaded="addGalleryUpload"/></div>
      <el-form v-if="activeTab==='boundaries'" label-position="top"><el-form-item label="能力边界（每行一项）"><el-input v-model="boundariesText" type="textarea" :rows="10"/></el-form-item></el-form>
      <div v-if="activeTab==='tender'" class="tender-editor"><div class="section-head"><div><h2>招投标参数</h2><p>此处为独立、可复用的投标技术口径。</p></div><el-button :icon="Plus" @click="tenderFields.push({name:'',value:'',unit:'',group:'基础参数',highlight:false,dataType:'TEXT'})">新增参数</el-button></div><div v-for="(field,index) in tenderFields" :key="index"><el-input v-model="field.group" placeholder="参数组"/><el-input v-model="field.name" placeholder="参数名称"/><el-input v-model="field.value" placeholder="技术要求"/><el-input v-model="field.unit" placeholder="单位"/><el-button :icon="Remove" circle type="danger" plain @click="tenderFields.splice(index,1)"/></div></div>
    </div>

    <div v-else class="product-layout"><main>
      <template v-if="activeTab==='overview'"><div class="overview-grid"><section class="product-section overview-copy"><div class="section-head"><div><h2>产品概览与主要特性</h2><p>{{ record.description || record.summary }}</p></div></div><div v-if="record.features?.length" class="feature-grid"><article v-for="(item,index) in record.features" :key="item.id||item.title"><span>{{ String(index+1).padStart(2,'0') }}</span><div><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div></article></div><el-empty v-else description="主要特性待完善" :image-size="56"/></section><section class="product-section"><div class="section-head"><div><h2>核心应用场景</h2><p>从真实场景关系读取。</p></div></div><div class="mini-grid"><button v-for="relation in relationGroups.scenes" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.meta?.recommendationReason || relation.summary || '查看场景' }}</span></button></div><el-empty v-if="!relationGroups.scenes?.length" description="暂无推荐场景" :image-size="56"/></section></div><section class="product-section"><div class="section-head"><div><h2>配套推荐</h2><p>软件、算法、模型能力与设备采用分层视觉。</p></div><el-button v-if="canManage" :icon="Link" @click="emit('relate','all')">维护关系</el-button></div><div class="recommend-grid"><button v-for="relation in allRelations.slice(0,8)" :key="relation.type+relation.id" :class="'kind-'+relation.type" @click="emit('openRelation',relation)"><small>{{ relationLabel(relation.type) }}</small><strong>{{ relation.name }}</strong><span>{{ relation.meta?.purpose || relation.summary || '查看详情' }}</span></button></div><el-empty v-if="!allRelations.length" description="暂无配套推荐" :image-size="56"/></section></template>
      <section v-else-if="activeTab==='parameters'" class="product-section"><div class="section-head"><div><h2>技术参数</h2><p>按业务分组展示，重点参数同步至首屏。</p></div><el-button v-if="canManage" :icon="Edit" @click="beginEdit">编辑参数</el-button></div><div class="parameter-groups"><article v-for="(items,group) in groupedParameters" :key="group"><h3>{{ group }}</h3><dl><div v-for="item in items" :key="item.id||item.name" :class="{highlight:item.highlight}"><dt>{{ item.name }}</dt><dd>{{ item.value }}{{ item.unit }}</dd></div></dl></article></div><el-empty v-if="!record.parameters?.length" description="暂无产品参数"/></section>
      <section v-else-if="activeTab==='models'" class="product-section relation-section"><div class="section-head"><div><h2>模型能力</h2><p>展示支持版本、并发与支持状态。</p></div><el-button v-if="canManage" :icon="Link" @click="emit('relate','model-capabilities')">维护关系</el-button></div><div class="relation-cards"><button v-for="relation in relationGroups['model-capabilities']" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.meta?.supportVersion || '版本待确认' }} · 推荐并发 {{ relation.meta?.recommendedConcurrency || '-' }} · {{ relation.meta?.supportStatus || '支持状态待确认' }}</span></button></div><el-empty v-if="!relationGroups['model-capabilities']?.length" description="暂无模型能力关联"/></section>
      <section v-else-if="activeTab==='software'" class="product-section relation-section"><div class="section-head"><div><h2>软件与算法</h2><p>SUPPORT 与 COMMERCIALIZATION 关系分别展示。</p></div><el-button v-if="canManage" :icon="Link" @click="emit('relate','software')">维护关系</el-button></div><div class="relation-columns"><div><h3>软件资产</h3><button v-for="relation in relationGroups.software" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.relationType==='COMMERCIALIZATION'?'商业化映射':'支持/依赖' }} · {{ relation.meta?.minimumVersion || '版本待确认' }}</span></button></div><div><h3>算法能力</h3><button v-for="relation in relationGroups.algorithms" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.meta?.purpose || '用途待确认' }}</span></button></div></div></section>
      <section v-else-if="activeTab==='boundaries'" class="product-section"><div class="section-head"><div><h2>能力边界</h2><p>明确产品适用限制，避免超范围承诺。</p></div></div><div class="boundary-list"><article v-for="(item,index) in record.boundaries" :key="item"><span>{{ index+1 }}</span><p>{{ item }}</p></article></div><el-empty v-if="!record.boundaries?.length" description="能力边界待完善"/></section>
      <section v-else-if="activeTab==='scenes'" class="product-section relation-section"><div class="section-head"><div><h2>推荐场景与方案</h2><p>关系来自六大中心统一关系底座。</p></div><el-button v-if="canManage" :icon="Link" @click="emit('relate','scenes')">维护关系</el-button></div><div class="relation-columns"><div><h3>推荐场景</h3><button v-for="relation in relationGroups.scenes" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.meta?.recommendationReason || '查看适用场景' }}</span></button></div><div><h3>相关方案</h3><button v-for="relation in relationGroups.solutions" :key="relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><span>{{ relation.meta?.purpose || '查看方案配置' }}</span></button></div></div></section>
      <section v-else-if="activeTab==='price' && showPrice" class="product-section"><div class="section-head"><div><h2>价格信息</h2><p>价格字段仅向具备 PRICE_VIEW 的身份返回和展示。</p></div><el-button v-if="canManage&&!priceEditing" :icon="Edit" @click="beginPriceEdit">维护价格</el-button></div><el-form v-if="priceEditing" label-position="top" class="edit-grid"><el-form-item label="参考价格"><el-input-number v-model="priceDraft.reference_price" :min="0" :precision="2" style="width:100%"/></el-form-item><el-form-item label="币种"><el-select v-model="priceDraft.currency"><el-option label="人民币" value="CNY"/></el-select></el-form-item><el-form-item label="含税"><el-switch v-model="priceDraft.tax_included"/></el-form-item><el-form-item label="税率 (%)"><el-input-number v-model="priceDraft.tax_rate" :min="0" :max="100"/></el-form-item><el-form-item label="有效期"><el-date-picker v-model="priceDraft.valid_until" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="priceDraft.notes"/></el-form-item><div class="span-2 price-actions"><el-button @click="priceEditing=false">取消</el-button><el-button type="primary" @click="savePrice">保存价格</el-button></div></el-form><div v-else-if="record.price" class="price-detail"><strong>{{ money() }}</strong><dl><div><dt>计税方式</dt><dd>{{ record.price.taxIncluded?'含税':'未税' }}</dd></div><div><dt>税率</dt><dd>{{ record.price.taxRate }}%</dd></div><div><dt>有效期</dt><dd>{{ record.price.validUntil?.slice(0,10) || '待确认' }}</dd></div><div><dt>说明</dt><dd>{{ record.price.notes || '无' }}</dd></div></dl></div><el-empty v-else description="暂无价格信息"/></section>
      <section v-else-if="activeTab==='tender'" class="product-section"><div class="section-head"><div><h2>招投标参数</h2><p>独立维护可复用的投标技术口径。</p></div><el-button v-if="canManage" :icon="Edit" @click="beginEdit">原位编辑</el-button></div><el-table :data="record.tenderParameters||record.parameters||[]"><el-table-column prop="group" label="参数组"/><el-table-column prop="name" label="参数名称"/><el-table-column label="技术要求"><template #default="scope">{{ scope.row.value }}{{ scope.row.unit }}</template></el-table-column></el-table></section>
      <section v-else-if="activeTab==='documents'" class="product-section"><DocumentAssets center-type="products" :center-id="record.id" :can-manage="canManage" :can-download="canDownload"/></section>
      <section v-else-if="activeTab==='training'" class="product-section"><div class="section-head"><div><h2>相关培训</h2><p>培训课程关系入口，本轮不扩展培训系统。</p></div></div><el-empty description="暂无关联培训课程"/></section>
